// ─────────────────────────────────────────────────────────────────────────────
// Account-area models added for the Nexion portal rebuild (2026-09-06).
//
// Each exists because a CONCEPT SCREEN needs it and nothing in the schema could
// answer it. They are additive — no existing model or column changes — so an
// older deployment keeps working and these simply stay empty until used.
// ─────────────────────────────────────────────────────────────────────────────

/// A customer-issued API key. The Settings concept lists these with a scope and
/// a last-used time, and says "keys are shown once" — so only a HASH is stored
/// and the plaintext exists exactly once, in the response that creates it.
model ApiKey {
  id         String    @id @default(cuid())
  userId     String
  user       User      @relation(fields: [userId], references: [id], onDelete: Cascade)
  name       String
  /// SHA-256 of the full key. Never the key itself — a leaked table must not be
  /// a leaked set of credentials.
  keyHash    String    @unique
  /// First 12 chars ("nxk_live_4f8a"), for showing which key a row refers to.
  prefix     String
  /// Coarse scope, e.g. "full" | "servers:read" | "metrics:read".
  scope      String    @default("full")
  lastUsedAt DateTime?
  revokedAt  DateTime?
  createdAt  DateTime  @default(now())

  @@index([userId, createdAt])
}

/// A signed-in device. The Settings concept lists location, device and IP with
/// a Revoke action, which needs a record per session rather than a bare cookie.
model UserSession {
  id         String    @id @default(cuid())
  userId     String
  user       User      @relation(fields: [userId], references: [id], onDelete: Cascade)
  /// SHA-256 of the session token, for the same reason as ApiKey.keyHash.
  tokenHash  String    @unique
  userAgent  String?
  ip         String?
  /// Resolved city/country for display. Null when geo lookup is unavailable —
  /// the UI says "Unknown location" rather than inventing one.
  location   String?
  lastSeenAt DateTime  @default(now())
  revokedAt  DateTime?
  createdAt  DateTime  @default(now())

  @@index([userId, lastSeenAt])
}

/// Per-account display preferences. Everything here is DISPLAY ONLY — none of
/// it may influence what is charged. `currency` in particular is the display
/// currency the portal already converts with; money is decided in USD cents
/// server-side regardless of what this says.
model UserPreference {
  userId          String   @id
  user            User     @relation(fields: [userId], references: [id], onDelete: Cascade)
  theme           String   @default("dark") // dark | light | system
  defaultPage     String   @default("/dashboard")
  itemsPerPage    Int      @default(25)
  dateFormat      String   @default("DMY") // DMY | MDY | ISO
  displayCurrency String   @default("USD")
  /**
   * NOTIFICATION PREFERENCES ARE NOT HERE, deliberately. They already live in
   * `User.notificationPrefs` behind lib/prefs.ts, which owns the policy that
   * decides which messages a preference is even ALLOWED to suppress — a
   * declined payment, an imminent suspension or a 2FA change is delivered
   * whatever the customer ticked. Adding `notifyBilling` here would have been a
   * second store the send path never reads: exactly the defect that file was
   * written to fix, where a control reported success and governed nothing.
   */
  updatedAt       DateTime @updatedAt
}

/// One hit on a referral or partner link. The concept screens show a conversion
/// rate ("18.4% of 125 clicks") and a referral count over time; without a click
/// row there is no denominator and the figure cannot be shown honestly.
model ReferralClick {
  id              String   @id @default(cuid())
  /// The code from the link — User.referralCode or ReferralPartner.code.
  code            String
  /// Set once a signup is attributed to this click.
  convertedUserId String?
  ipHash          String?
  referer         String?
  createdAt       DateTime @default(now())

  @@index([code, createdAt])
}

/// An outstanding invitation to an organisation. The Team concept shows pending
/// invites with a role and an expiry, and states invites expire in 7 days.
model OrgInvite {
  id          String       @id @default(cuid())
  orgId       String
  org         Organization @relation(fields: [orgId], references: [id], onDelete: Cascade)
  email       String
  role        String       @default("MEMBER")
  /// SHA-256 of the accept token.
  tokenHash   String       @unique
  invitedById String?
  expiresAt   DateTime
  acceptedAt  DateTime?
  revokedAt   DateTime?
  createdAt   DateTime     @default(now())

  @@unique([orgId, email])
  @@index([orgId, createdAt])
}

