     8	/* Settings actions for the account area.
     9	 *
    10	 * `"use server"` makes EVERY export here network-callable, so each one calls
    11	 * `requireUser()` itself and scopes every write to that user's own id. There is
    12	 * no shared "already checked" state between them — a caller reaching one export
    13	 * directly must be authorised by that export.
    14	 *
    15	 * Nothing here touches money, notification delivery, or anything that could
    16	 * suppress a message: notification preferences live in `User.notificationPrefs`
    17	 * behind lib/prefs.ts, which owns the policy about what may be suppressed.
    18	 */
    19	
    20	export type Res = { ok?: boolean; error?: string; value?: string };
    21	
    22	const THEMES = new Set(["dark", "light", "system"]);
    23	const DATE_FORMATS = new Set(["DMY", "MDY", "ISO"]);
    24	const PER_PAGE = new Set([10, 25, 50, 100]);
    25	
    26	/** Display preferences. Display only — none of this decides what is charged. */
    27	export async function saveDisplayPrefs(_p: Res | undefined, form: FormData): Promise<Res> {
    28	  const user = await requireUser();
    29	  const theme = String(form.get("theme") ?? "dark");
    30	  const dateFormat = String(form.get("dateFormat") ?? "DMY");
    31	  const itemsPerPage = Number(form.get("itemsPerPage") ?? 25);
    32	  const defaultPage = String(form.get("defaultPage") ?? "/dashboard");
    33	
    34	  /* Validated against a closed set rather than stored as typed. A free string
    35	     here would come back out into a `className` or a route. */
    36	  if (!THEMES.has(theme)) return { error: "Unknown theme." };
    37	  if (!DATE_FORMATS.has(dateFormat)) return { error: "Unknown date format." };
    38	  if (!PER_PAGE.has(itemsPerPage)) return { error: "Unsupported page size." };
    39	  if (!defaultPage.startsWith("/dashboard")) return { error: "That page is not a dashboard page." };
    40	
    41	  await db.userPreference.upsert({
    42	    where: { userId: user.id },
    43	    create: { userId: user.id, theme, dateFormat, itemsPerPage, defaultPage },
    44	    update: { theme, dateFormat, itemsPerPage, defaultPage },
    45	  });
    46	  revalidatePath("/dashboard/settings");
    47	  return { ok: true };
    48	}
    49	
    50	/** Issue an API key. The plaintext is returned ONCE and never stored. */
    51	export async function createApiKey(_p: Res | undefined, form: FormData): Promise<Res> {
    52	  const user = await requireUser();
    53	  const name = String(form.get("name") ?? "").trim().slice(0, 60);
    54	  const scope = String(form.get("scope") ?? "full");
    55	  if (name.length < 2) return { error: "Give the key a name you will recognise later." };
    56	  if (!["full", "servers:read", "metrics:read"].includes(scope)) return { error: "Unknown scope." };
    57	
    58	  const live = await db.apiKey.count({ where: { userId: user.id, revokedAt: null } });
    59	  if (live >= 20) return { error: "You already have 20 active keys. Revoke one first." };
    60	
    61	  /* 32 bytes of CSPRNG. The database gets only the SHA-256 and a display
    62	     prefix, so a dump of this table is not a set of working credentials. */
    63	  const secret = randomBytes(32).toString("base64url");
    64	  const key = `nxk_live_${secret}`;
    65	  await db.apiKey.create({
    66	    data: {
    67	      userId: user.id, name, scope,
    68	      keyHash: createHash("sha256").update(key).digest("hex"),
    69	      prefix: key.slice(0, 13),
    70	    },
    71	  });
    72	  revalidatePath("/dashboard/settings");
    73	  /* The one and only time this value exists outside the caller's hands. */
    74	  return { ok: true, value: key };
    75	}
    76	
    77	export async function revokeApiKey(id: string): Promise<Res> {
    78	  const user = await requireUser();
    79	  /* Scoped to the caller's own id in the WHERE, not checked afterwards — a
    80	     mismatched id updates nothing rather than revoking someone else's key. */
    81	  const r = await db.apiKey.updateMany({
    82	    where: { id, userId: user.id, revokedAt: null },
    83	    data: { revokedAt: new Date() },
    84	  });
    85	  if (r.count === 0) return { error: "That key is already revoked, or is not yours." };
    86	  revalidatePath("/dashboard/settings");
    87	  return { ok: true };
    88	}
    89	
    90	export async function revokeSession(id: string): Promise<Res> {
    91	  const user = await requireUser();
    92	  const r = await db.userSession.updateMany({
    93	    where: { id, userId: user.id, revokedAt: null },
    94	    data: { revokedAt: new Date() },
    95	  });
    96	  if (r.count === 0) return { error: "That session has already ended." };
    97	  revalidatePath("/dashboard/settings");
    98	  return { ok: true };
    99	}
   100	
   101	/** End every OTHER session. The current one is left alone deliberately —
   102	 *  signing yourself out of the page you are standing on is not what the
   103	 *  control means. */
   104	export async function revokeOtherSessions(currentTokenHash: string): Promise<Res> {
   105	  const user = await requireUser();
   106	  const r = await db.userSession.updateMany({
   107	    where: { userId: user.id, revokedAt: null, NOT: { tokenHash: currentTokenHash } },
   108	    data: { revokedAt: new Date() },
   109	  });
   110	  revalidatePath("/dashboard/settings");
   111	  return { ok: true, value: String(r.count) };
