export const dynamic = "force-dynamic";

import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { normalizePrefs } from "@/lib/prefs";
import { SettingsAurora } from "@/components/nx/SettingsAurora";
import { SettingsView } from "@/components/nx/SettingsView";
import { getCloudflareStatus } from "@/lib/actions-cloudflare";
import { getMyDiscordLinkStatus } from "@/lib/actions-discord-link-customer";
import { platformKeyConfigured } from "@/lib/anthropic";

/* Account settings, on the concept's hero + left-rail layout.
 *
 * Every control here writes through a real server action. The concept screen
 * also shows Company, Country, Timezone and Language fields and a Dashboard
 * View picker; none of those exist as columns on this account model, so they
 * are absent rather than drawn as inputs that would discard what you typed.
 */
export default async function SettingsPage() {
  const user = await requireUser();

  /* Integration state comes from the same server helpers the live portal uses,
     so "connected" here means a token really is stored, and a Connect button is
     only offered where that provider's OAuth is actually configured. */
  const [prefs, sshKeys, apiKeys, sessions, cloudflare, discord] = await Promise.all([
    db.userPreference.findUnique({ where: { userId: user.id } }),
    db.sshKey.findMany({
      where: { userId: user.id },
      select: { id: true, name: true, createdAt: true, publicKey: true },
      orderBy: { createdAt: "desc" },
    }),
    db.apiKey.findMany({
      where: { userId: user.id, revokedAt: null },
      select: { id: true, name: true, prefix: true, scope: true, lastUsedAt: true, createdAt: true },
      orderBy: { createdAt: "desc" },
    }),
    db.userSession.findMany({
      where: { userId: user.id, revokedAt: null },
      select: { id: true, userAgent: true, ip: true, location: true, lastSeenAt: true },
      orderBy: { lastSeenAt: "desc" },
      take: 20,
    }),
    getCloudflareStatus().catch(() => null),
    getMyDiscordLinkStatus().catch(() => null),
  ]);

  return (
    <>
      <SettingsAurora />

      {/* relative + z-1: the aurora is a POSITIONED (fixed, z-0) layer, so it
          paints above ordinary static content unless the page gets its own. */}
      <div className="relative z-[1] mx-auto flex w-full max-w-[1520px] flex-col gap-5">
        <header className="relative min-h-[132px] rounded-[18px]">
          <span aria-hidden className="absolute right-2 top-1/2 hidden -translate-y-1/2 flex-col items-end gap-[7px] xl:flex">
            {["SAME INFRASTRUCTURE.", "A BRIGHTER", "TOMORROW."].map((l) => (
              <span key={l} className="text-[10.5px] font-semibold uppercase tracking-[0.32em] text-[#a892ff]">{l}</span>
            ))}
          </span>

          <div className="relative max-w-[640px] px-1 pb-5 pt-6">
            <span className="text-[11px] font-extrabold uppercase tracking-[0.26em] text-[#7f9ad0]">Settings</span>
            <h1 className="mt-2 text-[36px] font-extrabold leading-[1.02] tracking-[-0.035em] text-white sm:text-[42px]">
              Account <span className="grad-text">Settings</span>
            </h1>
            <p className="mt-2.5 text-[14.5px] text-tx-dim">
              Manage your account, preferences, and infrastructure settings.
            </p>
          </div>
        </header>

        <SettingsView
          profile={{
            name: user.name,
            email: user.email,
            avatarUrl: user.avatarUrl ?? null,
            joined: user.createdAt.toISOString(),
            role: user.role,
            /* Real 2FA state, from the column the login path actually checks. */
            totpEnabled: user.totpEnabled,
            emailVerified: user.emailVerifiedAt !== null,
          }}
          prefs={{
            theme: prefs?.theme ?? "dark",
            dateFormat: prefs?.dateFormat ?? "DMY",
            itemsPerPage: prefs?.itemsPerPage ?? 25,
            defaultPage: prefs?.defaultPage ?? "/dashboard",
          }}
          /* The notification tiers come from lib/prefs.ts's own catalogue, so the
             page cannot offer a toggle the send policy does not honour. */
          notify={normalizePrefs(user.notificationPrefs)}
          sshKeys={sshKeys.map((k) => ({
            id: k.id, name: k.name, created: k.createdAt.toISOString(),
            /* Fingerprint-ish tail only. The full key is not needed to identify a
               row and putting it in the page just widens what a screenshot leaks. */
            tail: k.publicKey.trim().split(/\s+/).slice(-1)[0]?.slice(-24) ?? "",
          }))}
          apiKeys={apiKeys.map((k) => ({
            id: k.id, name: k.name, prefix: k.prefix, scope: k.scope,
            lastUsed: k.lastUsedAt?.toISOString() ?? null,
            created: k.createdAt.toISOString(),
          }))}
          sessions={sessions.map((s) => ({
            id: s.id, userAgent: s.userAgent, ip: s.ip, location: s.location,
            lastSeen: s.lastSeenAt.toISOString(),
          }))}
          integrations={{
            /* A provider whose status call failed is shown as not connected and
               not connectable, which is the honest reading of "we couldn't ask". */
            cloudflare: cloudflare ?? { connected: false, kind: null, oauthAvailable: false, scopeSummary: "" },
            anthropic: { connected: Boolean(user.anthropicKeyEnc), platformKey: platformKeyConfigured() },
            discord: discord ?? { connected: false, username: null, oauthAvailable: false },
          }}
        />
      </div>
    </>
  );
}

